import base64,json,linecache,sys,types,unittest
assert 'torch' not in sys.modules and 'torch_npu' not in sys.modules
sources={'owned_worker_cleanup': '', 'test_owned_cleanup_cpu': ''}
for name,encoded in sources.items():
    source=base64.b64decode(encoded).decode();filename='/CPU-only-v6/'+name+'.py'
    module=types.ModuleType(name);module.__file__=filename;sys.modules[name]=module
    linecache.cache[filename]=(len(source),None,source.splitlines(keepends=True),filename)
    exec(compile(source,filename,'exec'),module.__dict__)
result=unittest.TextTestRunner(stream=sys.stderr,verbosity=2).run(unittest.defaultTestLoader.loadTestsFromModule(sys.modules['test_owned_cleanup_cpu']))
assert not result.skipped
assert 'torch' not in sys.modules and 'torch_npu' not in sys.modules
print(json.dumps({'scope':'actual Linux CPU self-created child pidfd cleanup tests only','tests':result.testsRun,
'passed':result.wasSuccessful(),'failures':len(result.failures),'errors':len(result.errors),'skipped':len(result.skipped),
'npu_jobs':0,'torch_npu_imported':False,'device_audit_passed':False,'safe_formal_receipt':False},indent=2))
raise SystemExit(0 if result.wasSuccessful() else 1)
